  "source": "// snake.zl - Snake for the 64x32 ZX-16 screen. Steer with arrow keys or WASD.\nconst SCREEN = 0xF000;   // framebuffer, one byte per pixel\nconst XS     = 0xF800;   // ring buffer with the x of every segment\nconst YS     = 0xF900;   // ring buffer with the y of every segment\nconst KEY    = 0xFF00;   // last key pressed (we clear it after reading)\nconst TIMER  = 0xFF02;\nconst HEAD   = 0xFC00;   // index of the head in the ring buffers\nconst TAIL   = 0xFC02;\nconst DIR    = 0xFC04;   // 1 up, 2 down, 3 left, 4 right\nconst SEED   = 0xFC06;\nconst SCORE  = 0xFC08;\n\nconst WALL = 5;\nconst BODY = 11;\nconst HEADC = 10;\nconst FOOD = 8;\n\nfn pixel(x, y, c) {\n    pokeb(SCREEN + y * 64 + x, c);\n}\n\nfn get_pixel(x, y) {\n    return peekb(SCREEN + y * 64 + x);\n}\n\nfn rnd(n) {\n    var s = peek(SEED) * 25173 + 13849;\n    poke(SEED, s);\n    return (s >> 4) % n;\n}\n\nfn clear_screen() {\n    var i = 0;\n    while (i < 2048) {\n        pokeb(SCREEN + i, 0);\n        i = i + 1;\n    }\n}\n\nfn draw_walls() {\n    var i = 0;\n    while (i < 64) {\n        pixel(i, 0, WALL);\n        pixel(i, 31, WALL);\n        i = i + 1;\n    }\n    i = 0;\n    while (i < 32) {\n        pixel(0, i, WALL);\n        pixel(63, i, WALL);\n        i = i + 1;\n    }\n}\n\nfn place_food() {\n    while (1) {\n        var x = 1 + rnd(62);\n        var y = 1 + rnd(30);\n        if (get_pixel(x, y) == 0) {\n            pixel(x, y, FOOD);\n            return 0;\n        }\n    }\n}\n\nfn read_dir() {\n    var k = peek(KEY);\n    if (k != 0) {\n        poke(KEY, 0);\n        var d = peek(DIR);\n        if ((k == 1 || k == 'w') && d != 2) { poke(DIR, 1); }\n        if ((k == 2 || k == 's') && d != 1) { poke(DIR, 2); }\n        if ((k == 3 || k == 'a') && d != 4) { poke(DIR, 3); }\n        if ((k == 4 || k == 'd') && d != 3) { poke(DIR, 4); }\n    }\n}\n\n// plays one game, returns the score\nfn play() {\n    clear_screen();\n    draw_walls();\n    var i = 0;\n    while (i < 3) {\n        pokeb(XS + i, 28 + i);\n        pokeb(YS + i, 16);\n        pixel(28 + i, 16, BODY);\n        i = i + 1;\n    }\n    pixel(30, 16, HEADC);\n    poke(HEAD, 2);\n    poke(TAIL, 0);\n    poke(DIR, 4);\n    poke(SCORE, 0);\n    place_food();\n\n    while (1) {\n        read_dir();\n        var h = peek(HEAD);\n        var x = peekb(XS + h);\n        var y = peekb(YS + h);\n        var d = peek(DIR);\n        if (d == 1) { y = y - 1; }\n        if (d == 2) { y = y + 1; }\n        if (d == 3) { x = x - 1; }\n        if (d == 4) { x = x + 1; }\n\n        var c = get_pixel(x, y);\n        if (c != 0 && c != FOOD) {\n            return peek(SCORE);\n        }\n\n        pixel(peekb(XS + h), peekb(YS + h), BODY);\n        h = (h + 1) & 255;\n        pokeb(XS + h, x);\n        pokeb(YS + h, y);\n        poke(HEAD, h);\n        pixel(x, y, HEADC);\n\n        if (c == FOOD) {\n            poke(SCORE, peek(SCORE) + 1);\n            place_food();\n        } else {\n            var t = peek(TAIL);\n            pixel(peekb(XS + t), peekb(YS + t), 0);\n            poke(TAIL, (t + 1) & 255);\n        }\n        sleep(70);\n    }\n    return 0;\n}\n\nfn main() {\n    poke(SEED, peek(TIMER) + 1);\n    puts(\"SNAKE - arrows or WASD to steer\\n\");\n    while (1) {\n        var score = play();\n        puts(\"GAME OVER, score: \");\n        print(score);\n        putc('\\n');\n        sleep(1500);\n    }\n}\n",
