  "lang": "zl",
  "source": "// fib.zl - recursive Fibonacci\nfn fib(n) {\n    if (n < 2) {\n        return n;\n    }\n    return fib(n - 1) + fib(n - 2);\n}\n\nfn main() {\n    var i = 0;\n    while (i < 15) {\n        print(fib(i));\n        putc(' ');\n        i = i + 1;\n    }\n    putc('\\n');\n}\n",
