  "source": "// primes.zl - primes below 60\nfn is_prime(n) {\n    var d = 2;\n    while (d * d <= n) {\n        if (n % d == 0) {\n            return 0;\n        }\n        d = d + 1;\n    }\n    return 1;\n}\n\nfn main() {\n    var n = 2;\n    while (n < 60) {\n        if (is_prime(n)) {\n            print(n);\n            putc(' ');\n        }\n        n = n + 1;\n    }\n    putc('\\n');\n}\n",
