  "lang": "zl",
  "source": "// ops.zl - operator precedence, comparisons, logic and argument order\nfn show(x) {\n    print(x);\n    putc(' ');\n}\n\nfn sub3(a, b, c) {\n    return a - b - c;\n}\n\nfn main() {\n    show(2 + 3 * 4);        // 14\n    show((2 + 3) * 4);      // 20\n    show(7 - 2 - 1);        // 4\n    show(100 / 7 % 5);      // 4\n    show(1 << 4 | 3);       // 19\n    show(1 < 2 && 3 > 2);   // 1\n    show(2 < 1 || 3 > 5);   // 0\n    show(!0);               // 1\n    show(-5 + 8);           // 3\n    show(sub3(10, 3, 2));   // 5\n    show(5 <= 5);           // 1\n    show(6 >= 7);           // 0\n    show(3 != 3);           // 0\n    show(0 - 3 < 2);        // 1 (comparisons are signed)\n    show(!5);               // 0\n    putc('\\n');\n}\n",
