  "source": "; primes.zasm - primes below 60, uses call/ret and the stack\nstart:\n    ldi  r1, 2          ; n\nnext_n:\n    cmpi r1, 60\n    jge  finish\n    call is_prime       ; in: r1 = n, out: r0 = 1 if prime\n    cmpi r0, 0\n    jz   skip\n    outn r1\n    ldi  r0, ' '\n    out  r0\nskip:\n    addi r1, 1\n    jmp  next_n\nfinish:\n    ldi  r0, '\\n'\n    out  r0\n    halt\n\n; is_prime: r1 = n -> r0 = 1/0. Clobbers r2, r3.\nis_prime:\n    ldi  r2, 2          ; d = 2\nip_loop:\n    mov  r3, r2\n    mul  r3, r3         ; d*d\n    cmp  r1, r3\n    jlt  ip_yes         ; n < d*d  -> prime\n    mov  r3, r1\n    mod  r3, r2         ; n % d\n    cmpi r3, 0\n    jz   ip_no\n    addi r2, 1\n    jmp  ip_loop\nip_yes:\n    ldi  r0, 1\n    ret\nip_no:\n    ldi  r0, 0\n    ret\n",
